package com.compatibleimgui.mixin.minecraft;

import com.compatibleimgui.shader.ShaderPatches;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Constant;
import org.spongepowered.asm.mixin.injection.ModifyConstant;
import org.spongepowered.asm.mixin.injection.Redirect;

import java.util.Locale;

/**
 * Keeps the uniform names used for reflection in sync with the Android-safe
 * names generated by {@link MixinGlPipelineRecompiler}.
 *
 * <p>The OpenGL backend computes {@code _uniform_<set>_<binding>} and
 * {@code _push_constants} again when it looks up block/uniform locations.
 * Both sides must be renamed together (including replacing the literal
 * {@code uniform} substring), otherwise uniforms silently stop being bound
 * after the shader source is patched.</p>
 */
@Mixin(targets = "com.mojang.renderpearl.backend.opengl.GlProgram", remap = false)
public abstract class MixinGlProgram {

    @Redirect(
        method = "setupBindGroupLayouts",
        at = @At(
            value = "INVOKE",
            target = "Ljava/lang/String;format(Ljava/util/Locale;Ljava/lang/String;[Ljava/lang/Object;)Ljava/lang/String;"
        ),
        remap = false,
        require = 0
    )
    private static String compatibleimgui$safeUniformName(
        Locale locale, String format, Object[] args
    ) {
        String name = String.format(locale, format, args);
        if (format.startsWith("_uniform_")) {
            return ShaderPatches.safeName(name);
        }
        return name;
    }

    @ModifyConstant(
        method = "setupBindGroupLayouts",
        constant = @Constant(stringValue = "_push_constants"),
        remap = false,
        require = 0
    )
    private static String compatibleimgui$safePushConstantsName(String name) {
        return ShaderPatches.safeName(name);
    }
}
